def check_large(n, bit_length):
    # n is 2**bit_length - 1, so across 0..n every bit position is set in exactly half of the numbers.
    bits = count_bits(n)
    if len(bits) != n + 1:
        raise AssertionError(f"count_bits({n}) should return {n + 1} items, got {len(bits)}")
    if sum(bits) != bit_length * 2 ** (bit_length - 1):
        raise AssertionError(f"the counts for 0..{n} should add up to {bit_length * 2 ** (bit_length - 1)}, but add up to {sum(bits)}")
    for i in (1, 2, 3, 1000, 65535, 65536, n // 2, n // 2 + 1, n * 3 // 4, n):
        if bits[i] != bin(i).count("1"):
            raise AssertionError(f"count_bits({n})[{i}] should be {bin(i).count('1')}, got {bits[i]}")
    return True

solution:
def count_bits(n):
    bits = [0] * (n + 1)
    for i in range(1, n + 1):
        # i has the same 1 bits as i // 2 (its last bit dropped), plus one if that last bit is 1
        bits[i] = bits[i >> 1] + (i & 1)
    return bits
